for _ in range(n):
    row = list(map(int, input().split()))
    matrix.append(row)

# Function to compute maximum sum subarray using Kadane's algorithm
def kadane(arr):
    max_current = max_global = arr[0]
    for num in arr[1:]:
        max_current = max(num, max_current + num)
        max_global = max(max_global, max_current)
    return max_global

max_sum = float('-inf')

# Try all pairs of top and bottom rows
for top in range(n):
    for bottom in range(top, n):
        # Create array of column sums between top and bottom rows
        col_sums = []
        for col in range(n):
            col_sum = 0
            for row in range(top, bottom + 1):
                col_sum += matrix[row][col]
            col_sums.append(col_sum)

        # Find maximum sum subarray in this 1D array
        current_max = kadane(col_sums)
        if current_max > max_sum:
            max_sum = current_max

print(max_sum)
"}

