import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    idx = 0
    N = int(data[idx])
    idx += 1
    V = int(data[idx])
    idx += 1

    A = list(map(int, data[idx:idx+N]))
    idx += N
    B = list(map(int, data[idx:idx+N]))
    idx += N
    C = list(map(int, data[idx:idx+N]))
    idx += N
    D = list(map(int, data[idx:idx+N]))

    # Combine A and B
    ab_counts = {}
    for a in A:
        for b in B:
            s = a + b
            if s in ab_counts:
                ab_counts[s] += 1
            else:
                ab_counts[s] = 1

    # Combine with C
    abc_counts = {}
    for s_ab, count in ab_counts.items():
        for c in C:
            s = s_ab + c
            if s in abc_counts:
                abc_counts[s] += count
            else:
                abc_counts[s] = count

    # Combine with D
    abcd_counts = {}
    for s_abc, count in abc_counts.items():
        for d in D:
            s = s_abc + d
            if s in abcd_counts:
                abcd_counts[s] += count
            else:
                abcd_counts[s] = count

    print(abcd_counts.get(V, 0))

if __name__ == "__main__":
    solve()
