def is_palindrome(x):
    return str(x) == str(x)[::-1]

# Generate all palindromes up to n + 10000
n = int(input())
limit = n + 10000

# Generate palindromes by mirroring half the number
palindromes = []

# Generate palindromes of different lengths
for length in range(1, len(str(limit)) + 1):
    # Generate the first half of the palindrome
    for start in range(10**(length-1), 10**(length-1) + 10**(length//2)):
        half = str(start)

        # Create palindrome by mirroring
        if length % 2 == 0:
            palindrome = int(half + half[::-1])
        else:
            palindrome = int(half + half[:-1][::-1])

        if palindrome <= limit:
            palindromes.append(palindrome)

# Find the closest palindrome
min_distance = float('inf')
closest_palindrome = None

for palindrome in palindromes:
    distance = abs(palindrome - n)
    if distance < min_distance or (distance == min_distance and palindrome < closest_palindrome):
        min_distance = distance
        closest_palindrome = palindrome

print(closest_palindrome)
