def solve():
    n, m = map(int, input().split())
    leaders = list(map(int, input().split()))

    # If there's only one step, any permutation works
    if m == 1:
        a = list(range(1, n + 1))
        print(' '.join(map(str, a)))
        return

    # For each position, determine what a[p] should be
    # We'll store expected values for each position
    expected = {}

    # Check if the sequence is possible
    for i in range(m - 1):
        current = leaders[i]
        next_leader = leaders[i + 1]

        if current == next_leader:
            # Must stay at the same position, so a[current] = n
            if current in expected and expected[current] != n:
                print(-1)
                return
            expected[current] = n
        else:
            # Compute a[current]
            if next_leader >= current:
                k = next_leader - current
            else:
                k = n - (current - next_leader)

            if current in expected and expected[current] != k:
                print(-1)
                return
            expected[current] = k

    # Now check if all positions have values assigned
    # And if there are any duplicates (since each value from 1..n must appear exactly once)
    assigned = set()

    for pos in expected:
        val = expected[pos]
        if val in assigned:
            print(-1)
            return
        assigned.add(val)

    # Check if any position is missing a value (shouldn't happen if valid)
    for pos in range(1, n + 1):
        if pos not in expected:
            # We need to assign a default value
            # Try all values not used yet
            for candidate in range(1, n + 1):
                if candidate not in assigned:
                    expected[pos] = candidate
                    assigned.add(candidate)
                    break

    # Print the permutation
    a = [0] * (n + 1)
    for pos, val in expected.items():
        a[pos] = val

    print(' '.join(map(str, a[1:])))

solve()
"}

