    index += 1
    strengths = list(map(int, lines[index].split()))
    index += 1
    # If there's a 0, the team size should be 1 (or maybe 0?)
    if 0 in strengths:
        result = 1
    else:
        result = gcd_multiple(strengths)
    print(result)
