    for _ in range(T):
        N, K = int(data[idx]), int(data[idx+1])
        idx += 2

        total = 0
        for _ in range(N):
            a = int(data[idx])
            idx += 1

            if a % K != 0:
                remainder = a % K

                if a < K:
                    # Can't remove, must add
                    total += (K - remainder)
                else:
                    # Choose min between remove and add
                    total += min(remainder, K - remainder)

        results.append(str(total))

    sys.stdout.write("\n".join(results))

