def find_meeting_round(n, a, b):
    # If they're already in the same half of the bracket
    if n % 2 == 0:
        half = n // 2
        if a <= half and b <= half:
            # They're in the same half, they'll meet in this half
            return 1 + find_meeting_round(half, a, b)
        elif a > half and b > half:
            # They're in the other half
            return 1 + find_meeting_round(n - half, a - half, b - half)
