def find_suffixes(s):
    """Find all distinct suffixes of length 2 or 3 that could appear in the word construction."""
    n = len(s)
    result = set()

    # Try all possible root starts
    for root_start in range(n - 4):  # root length ≥ 5
        suffix_part = s[root_start:]
        suffix_len = len(suffix_part)

        # If there are no suffixes, skip
        if suffix_len == 0:
            continue

        # Try all possible suffix sequences from right to left
        # dp[i] = set of suffixes that can appear starting at position i
        dp = [set() for _ in range(suffix_len)]

        # Base case: position suffix_len-1
        if suffix_len >= 2:
            dp[suffix_len-1].add(suffix_part[suffix_len-2:suffix_len])  # length 2 suffix
        if suffix_len >= 3:
            dp[suffix_len-1].add(suffix_part[suffix_len-3:suffix_len])  # length 3 suffix

        # Work backwards
        for i in range(suffix_len - 2, -1, -1):
            # Check suffix of length 2
            if suffix_len - i - 2 >= 2:
                suffix_2 = suffix_part[i:i+2]
                for prev_suffix in dp[i+2]:
                    if prev_suffix != suffix_2:
                        dp[i].add(suffix_2)

            # Check suffix of length 3
            if suffix_len - i - 3 >= 3:
                suffix_3 = suffix_part[i:i+3]
                for prev_suffix in dp[i+3]:
                    if prev_suffix != suffix_3:
                        dp[i].add(suffix_3)

        # Add all suffixes found for this root start
        for suffix in dp[0]:
            result.add(suffix)

    return sorted(result)

# Read input
