def get_oddness(team):
    """Return the oddness value of a team.
    This groups teams by their odd/even pattern.
    """
    if team % 2 == 1:
        return team
    else:
        return team - 1

n, a, b = map(int, input().split())

odd_a = get_oddness(a)
odd_b = get_oddness(b)

# Check if teams can meet in the final
# This happens if they are not consecutive in any earlier round
# So we look for the first round where they are consecutive
for r in range(1, n):
    block_size_half = 2 ** (r - 1) - 1
    if odd_a == odd_b and abs(odd_a - odd_b) == block_size_half:
        print(r)
        break
else:
    print("Final!")
