import sys

def find(parent, x):
    if parent[x] != x:
        parent[x] = find(parent, parent[x])
    return parent[x]

def union(parent, rank, x, y):
    root_x = find(parent, x)
    root_y = find(parent, y)
    if root_x == root_y:
        return False
    if rank[root_x] < rank[root_y]:
        parent[root_x] = root_y
    else:
        parent[root_y] = root_x
        if rank[root_x] == rank[root_y]:
            rank[root_x] += 1
    return True

def solve() -> None:
    input = sys.stdin.read()
    data = input.split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    k = int(next(it))

    # DSU for current connected components
    parent = list(range(n))
    rank = [1] * n

    # Set to track current edges
    current_edges = set()

    # Read all operations
    operations = []
    for _ in range(k):
        op = int(next(it))
        u = int(next(it))
        v = int(next(it))
        operations.append((op, u, v))

    output = []

    # Process each operation
    for op, u, v in operations:
        if op == 1:
            # Add edge
            if (u, v) not in current_edges and (v, u) not in current_edges:
                current_edges.add((u, v))
                if not union(parent, rank, u, v):
                    # Already connected, do nothing
                    pass
        elif op == 2:
            # Remove edge
            if (u, v) in current_edges or (v, u) in current_edges:
                if (u, v) in current_edges:
                    current_edges.remove((u, v))
                else:
                    current_edges.remove((v, u))

                # Rebuild DSU from scratch
                parent = list(range(n))
                rank = [1] * n
                for (a, b) in current_edges:
                    union(parent, rank, a, b)
        elif op == 3:
            # Query connectivity
            # Check if u and v are within bounds
            if 0 <= u < n and 0 <= v < n:
                try:
                    root_u = find(parent, u)
                    root_v = find(parent, v)
                    if root_u == root_v:
                        output.append("YES")
                    else:
                        output.append("NO")
                except IndexError:
                    output.append("NO")
            else:
                output.append("NO")

    sys.stdout.write("\n".join(output))

if __name__ == "__main__":
    solve()

