        # Find a vertex v such that distance(v, u) % k uniquely determines color
        found = False

        # Try each vertex as reference vertex
        for v in range(1, N + 1):
            # BFS to compute distances from v
            dist = [-1] * (N + 1)
            q = [v]
            dist[v] = 0

            while q:
                u = q.pop(0)
                for neighbor in graph[u]:
                    if dist[neighbor] == -1:
                        dist[neighbor] = dist[u] + 1
                        q.append(neighbor)

            # Check if this coloring works
            valid = True

            # For each pair of vertices (u, w)
            for u in range(1, N + 1):
                for w in range(u + 1, N + 1):
                    d = abs(dist[u] - dist[w])  # distance between u and w

