    N = int(next(it))

    # Build tree
    tree = [[] for _ in range(N + 1)]
    for _ in range(N - 1):
        a = int(next(it))
        b = int(next(it))
        tree[a].append(b)
        tree[b].append(a)

    # Compute distances from root (vertex 1)
    dist = [-1] * (N + 1)
    dist[1] = 0

    def bfs():
        from collections import deque
        q = deque([1])

        while q:
            u = q.popleft()
            for v in tree[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    q.append(v)

    bfs()

    # For each k, check if we can color the tree
    output = []

    for k in range(1, N + 1):
        # If k > max distance, all distances % k are unique, so we can color
        if k > max(dist[1:]):
            output.append('1')
            continue

        # If k == 1, all vertices must be the same color
        if k == 1:
            output.append('1')
            continue

        # Use colors = distance % k
        # Check if any two vertices at the same color have distance that is not a multiple of k
        ok = True

        # Check all pairs (i, j)
        for i in range(1, N + 1):
            for j in range(i + 1, N + 1):
                d = abs(dist[i] - dist[j])
                if d % k == 0:
                    if dist[i] % k != dist[j] % k:
                        ok = False
                        break
                else:
                    if dist[i] % k == dist[j] % k:
                        ok = False
                        break
            if not ok:
                break

        output.append('1' if ok else '0')

