import sys

def can_tile(n, m, blocked_cells):
    # Count unblocked cells
    total_unblocked = 2 * n
    unblocked = set()
    for r, c in blocked_cells:
        total_unblocked -= 1
    if total_unblocked % 2 != 0:
        return "NO"

    # Count unblocked cells in each row
    row1_unblocked = 0
    row2_unblocked = 0
    for r, c in blocked_cells:
        if r == 1:
            row1_unblocked += 1
        else:
            row2_unblocked += 1

    # If both rows have odd counts, we can't tile
    if row1_unblocked % 2 != 0 and row2_unblocked % 2 != 0:
        return "NO"

    # Check for odd-length contiguous blocks in each row
    unblocked_positions = {
        1: set(),
        2: set()
    }

    for r, c in blocked_cells:
        unblocked_positions[r].add(c)

    # Check row 1
    sorted_row1 = sorted(set(range(1, n + 1)) - unblocked_positions[1])
    for i in range(len(sorted_row1) - 1):
        if sorted_row1[i+1] - sorted_row1[i] == 1:
            # Adjacent cells, form a contiguous block
            # Count length of this block
            j = i
            while j + 1 < len(sorted_row1) and sorted_row1[j+1] - sorted_row1[j] == 1:
                j += 1
            if j - i + 1 % 2 != 0:
                return "NO"
            i = j

    # Check row 2
    sorted_row2 = sorted(set(range(1, n + 1)) - unblocked_positions[2])
    for i in range(len(sorted_row2) - 1):
        if sorted_row2[i+1] - sorted_row2[i] == 1:
            # Adjacent cells, form a contiguous block
            # Count length of this block
            j = i
            while j + 1 < len(sorted_row2) and sorted_row2[j+1] - sorted_row2[j] == 1:
                j += 1
            if j - i + 1 % 2 != 0:
                return "NO"
            i = j

    return "YES"

def solve():
    input = sys.stdin.read().strip().split()
    data = iter(input)

    t = int(next(data))

    for _ in range(t):
        # Skip empty lines
        while next(data, None) == "":
            pass

        n = int(next(data))
        m = int(next(data))

        blocked_cells = []
        for _ in range(m):
            r = int(next(data))
            c = int(next(data))
            blocked_cells.append((r, c))

        result = can_tile(n, m, blocked_cells)
        print(result)

solve()
