def solve():
    t = int(input())
    for _ in range(t):
        line = input().strip()
        if not line:
            continue
        n, k = map(int, line.split())
        if n == 1:
            print(1)
            continue

        # Factor n and get all divisors
        def get_divisors(n):
            i = 2
            factors = {}
            while i * i <= n:
                while n % i == 0:
                    factors[i] = factors.get(i, 0) + 1
                    n //= i
                i += 1
            if n > 1:
                factors[n] = 1
            divisors = {1}
            for p, e in factors.items():
                new_divs = set()
                for d in divisors:
                    for j in range(e + 1):
                        new_divs.add(d * (p ** j))
                divisors.update(new_divs)
            return sorted(divisors)

        divs = get_divisors(n)
        threshold = (n + k - 1) // k  # ceil(n/k) using integer arithmetic

        # Find smallest divisor >= threshold
        ans = n  # fallback
        for d in divs:
            if d >= threshold:
                ans = d
                break
        print(ans)

