import sys

def calculate_score(cards):
    """Calculate the score of a hand of cards"""
    # Cards 2-9 are as written
    # Cards 10-13 are 10 points
    # Card 1 can be 1 or 11
    # Try all combinations and find the max score <= 21

    max_score = 0

    # For each card, if it's 1, try both values (1 and 11)
    # For cards 2-9, just use the card
    # For cards 10-13, use 10

    # This is a brute force approach for small n (n ≤ 100)

    # Create a list of possible values for each card
    card_values = []
    for c in cards:
        if c == 1:
            card_values.append([1, 11])
        elif 2 <= c <= 9:
            card_values.append([c])
        elif 10 <= c <= 13:
            card_values.append([10])


    # Generate all combinations
    from itertools import product

    max_score = 0
    for combination in product(*card_values):
        score = sum(combination)
        if score > 21:
