if n == 1:
    print(-1)
else:
    # Find the smallest multiple of 210 with exactly n digits

    # For small n, we can compute directly
    if n <= 10:
        min_n_digit = 10 ** (n - 1)
        remainder = min_n_digit % 210
        if remainder == 0:
            print(min_n_digit)
        else:
            print(min_n_digit + (210 - remainder))
    else:
        # For large n, we need to be careful with big integers
        # Use sys.set_int_max_str_digits to handle large numbers
        import sys
        sys.set_int_max_str_digits(1000000)
        min_n_digit = 10 ** (n - 1)
        remainder = min_n_digit % 210
        if remainder == 0:
            print(min_n_digit)
        else:
            print(min_n_digit + (210 - remainder))
"}

