import math

n = int(input())

if n == 1:
    print(-1)
else:
    # Find the smallest multiple of 210 with exactly n digits

    # Compute 10^(n-1) mod 210
    remainder = pow(10, n-1, 210)

    # The smallest n-digit number is 10^(n-1)
    # We need to find the smallest multiple of 210 that is >= 10^(n-1)
    # This is 10^(n-1) if remainder == 0, otherwise 10^(n-1) + (210 - remainder)

    if remainder == 0:
        print('1' + '0' * (n-1))
    else:
        # Check if adding (210 - remainder) keeps it an n-digit number
        if remainder + 210 > 210:
            print(-1)
        else:
            # Construct the result string
            result = '1' + '0' * (n-1) + str(210 - remainder)
            print(result)
"}

