    y = input().strip()
    digits = list(y)
    total_sum = sum(int(d) for d in digits)

    # Check if total sum is divisible by 3
    if total_sum % 3 != 0:
        print("cyan")
        continue

    # Check if we can form a valid ending (00, 20, 40, 60, 80)
    can_form = False

    # Check for ending 00
    if digits.count('0') >= 2:
        can_form = True

    # Check for ending 20
    if digits.count('0') >= 1 and digits.count('2') >= 1:
        can_form = True

    # Check for ending 40
    if digits.count('0') >= 1 and digits.count('4') >= 1:
        can_form = True

    # Check for ending 60
    if digits.count('0') >= 1 and digits.count('6') >= 1:
        can_form = True

    # Check for ending 80
    if digits.count('0') >= 1 and digits.count('8') >= 1:
        can_form = True

    if can_form:
        print("red")
    else:
        print("cyan")
