import sys

def is_red(s):
    """Check if string s can be rearranged to form a number divisible by 60"""
    digits = list(s)
    count = {}

    # Count frequency of each digit
    for d in digits:
        count[d] = count.get(d, 0) + 1

    # Check if we can form a number ending with 00, 20, 40, 60, or 80
    # And check if sum of digits is divisible by 3

    # For divisibility by 20: last two digits must be 00, 20, 40, 60, or 80
    # For divisibility by 3: sum of all digits must be divisible by 3

    # Check if we can form a number ending with 00
    if count.get('0', 0) >= 2:
        if sum(int(d) for d in digits) % 3 == 0:
            return True

    # Check if we can form a number ending with 20
    if count.get('2', 0) >= 1 and count.get('0', 0) >= 1:
        if sum(int(d) for d in digits) % 3 == 0:
            return True

    # Check if we can form a number ending with 40
    if count.get('4', 0) >= 1 and count.get('0', 0) >= 1:
        if sum(int(d) for d in digits) % 3 == 0:
            return True

    # Check if we can form a number ending with 60
    if count.get('6', 0) >= 1 and count.get('0', 0) >= 1:
        if sum(int(d) for d in digits) % 3 == 0:
            return True

    # Check if we can form a number ending with 80
    if count.get('8', 0) >= 1 and count.get('0', 0) >= 1:
        if sum(int(d) for d in digits) % 3 == 0:
            return True

    return False

def main():
    n = int(sys.stdin.readline())
    for _ in range(n):
        s = sys.stdin.readline().strip()
        if is_red(s):
            print("red")
        else:
            print("cyan")

if __name__ == "__main__":
    main()
