import sys

def calculate_hand_score(cards):
    """Calculate the score of a hand in Blackjack."""
    # Separate card values
    tens = []  # cards with value 10 (10-13)
    ones = []  # cards with value 1
    twos_nines = []  # cards with value 2-9

    for card in cards:
        if 10 <= card <= 13:
            tens.append(10)
        elif card == 1:
            ones.append(1)
        else:  # 2-9
            twos_nines.append(card)

    # Calculate base score with all cards as their minimum values
    total = sum(tens) + sum(twos_nines) + sum(ones)

    # For each '1', try converting it to 11 (adding 10 more)
    for i in range(len(ones)):
        # Convert this '1' to 11
        new_total = total + 10

        # If the new total <= 21, update the total
        if new_total <= 21:
            total = new_total
            # Stop early if we've already used all '1's
            if i == len(ones) - 1:
                break

    return total if total <= 21 else 0

