    """Check if two paintings can be placed on a board"""

    # Check all 7 possible configurations
    # 1. Both stacked vertically
    if max(board_a, board_b) >= p1_a + p2_a and max(board_a, board_b) >= max(p1_b, p2_b):
        return True

    # 2. Both side by side horizontally
    if max(board_a, board_b) >= p1_b + p2_b and max(board_a, board_b) >= max(p1_a, p2_a):
        return True

    # 3. One on top of the other with one side aligned
    if max(board_a, board_b) >= p1_b + p2_b and max(board_a, board_b) >= max(p1_a, p2_a):
        return True

    # 4. One next to the other with one side aligned
    if max(board_a, board_b) >= p1_b + p2_b and max(board_a, board_b) >= max(p1_a, p2_a):
        return True

    # 5. One on top of the other with one side aligned (different orientation)
    if max(board_a, board_b) >= p1_a + p2_a and max(board_a, board_b) >= max(p1_b, p2_b):
        return True

    # 6. One next to the other with one side aligned (different orientation)
    if max(board_a, board_b) >= p1_b + p2_b and max(board_a, board_b) >= max(p1_a, p2_a):
        return True

    # 7. One on top of the other with one side aligned (different orientation)
    if max(board_a, board_b) >= p1_a + p2_a and max(board_a, board_b) >= max(p1_b, p2_b):
        return True

    # Check if we can place one painting next to the other with one side aligned
    if max(board_a, board_b) >= p1_b + p2_b and max(board_a, board_b) >= max(p1_a, p2_a):
        return True

    return False

