def find_suffixes(s):
    suffixes = set()
    n = len(s)

    # Try all possible root lengths
    for root_length in range(5, n):
        remaining = s[root_length:]

        # Check all possible ways to form suffixes from the remaining part
        # This is a dynamic programming problem
        def can_form(i, prev_suffix):
            # i is the current position in remaining
            # prev_suffix is the last suffix we used (to avoid repeats)
            if i == len(remaining):
                return True

            # Try using a suffix of length 2
            if i + 2 <= len(remaining):
                suffix = remaining[i:i+2]
                if suffix != prev_suffix:
                    if can_form(i + 2, suffix):
                        suffixes.add(suffix)
                        return True

            # Try using a suffix of length 3
            if i + 3 <= len(remaining):
                suffix = remaining[i:i+3]
                if suffix != prev_suffix:
                    if can_form(i + 3, suffix):
                        suffixes.add(suffix)
                        return True

            return False

        can_form(0, "")

    return sorted(suffixes)

