                continue
            # Check if yj's occurrence overlaps with yi's occurrence
            if yi + i == yj:
                # At position yi+i, yi's character is p[i]
                # At position yj, yj's character is p[0]
                if p[i] != p[0]:
                    consistent = False
                    break
            elif yi + i == yj + 1:
