def solve():
    n = int(input())
    s = input().strip()

    # Count occurrences of each letter
    count = {}
    for ch in s:
        if ch == '+':
            continue
        count[ch] = count.get(ch, 0) + 1

    # Extract the letters in order
    letters = [ch for ch in s if ch != '+']

    # Get the counts of each letter
    letter_counts = {ch: count[ch] for ch in letters}

    # Find the minimum and maximum count
    min_count = min(letter_counts.values())
    max_count = max(letter_counts.values())

    # If there's only one letter, just multiply it by its count
    if len(letter_counts) == 1:
        result = f"{list(letter_counts.keys())[0]} * {min_count}"
    else:
        # If all letters have the same count, group them
        if min_count == max_count:
            group = "+".join(letter_counts.keys())
            result = f"({group}) * {min_count}"
        else:
            # Otherwise, multiply each letter individually
            result = "+".join(f"{ch} * {cnt}" for ch, cnt in letter_counts.items())

    # Count the length of the result
    min_len = len(result)

    print(min_len)

solve()
