from collections import deque, defaultdict

def solve():
    n, m, k = map(int, input().split())
    grid = []
    start = None
    end = None

    for i in range(n):
        row = input().strip()
        grid.append(row)
        for j in range(m):
            if row[j] == 'S':
                start = (i, j)
            elif row[j] == 'T':
                end = (i, j)

    # Directions: up, right, down, left
    directions = [(-1, 0), (0, 1), (1, 0), (0, -1)]

    # BFS from S
    visited = defaultdict(set)
    queue = deque([(start[0], start[1], frozenset(), '')])
    visited[start[0]][start[1]].add((frozenset(), ''))

    while queue:
        r, c, types_visited, path = queue.popleft()

        # Check if we've reached T
        if (r, c) == end:
            print(path)
            return

        # Try all four directions
        for dr, dc in directions:
            nr, nc = r + dr, c + dc

            if 0 <= nr < n and 0 <= nc < m:
                # Check if cell is accessible
                cell = grid[nr][nc]

                if cell == 'T':
                    # We already reached T earlier, so skip
                    continue

                if cell == 'S':
                    # We should only visit S once at the start
                    continue

                # Check if we can visit this cell
                if cell in types_visited:
                    # Same type, can visit
                    new_types = types_visited
                else:
                    # New type, check if we can add it
                    if len(types_visited) < k:
                        new_types = types_visited | {cell}
                    else:
                        # Cannot add new type
                        continue

                # Check if we've visited this state before
                if (nr, nc, new_types) not in visited[nr]:
                    visited[nr][nc].add((new_types, path + cell))
                    queue.append((nr, nc, new_types, path + cell))

    # No path found
    print(-1)

solve()
