import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))

    masks = []
    for _ in range(n):
        k = int(next(it))
        mask = 0
        for _ in range(k):
            b = int(next(it))
            mask |= 1 << b
        masks.append(mask)

    q = int(next(it))

    state = 0  # All bits are OFF initially

    for _ in range(q):
        op = int(next(it))
        m = int(next(it))
        mask = masks[m]

        if op == 0:
            # test(i)
            i = m
            print(1 if (state >> i) & 1 else 0)
        elif op == 1:
            # set(m)
            state |= mask
        elif op == 2:
            # clear(m)
            state &= ~mask
        elif op == 3:
            # flip(m)
            state ^= mask
        elif op == 4:
            # all(m)
            all_on = True
            for i in range(64):
                if (mask >> i) & 1:
                    if not (state >> i) & 1:
                        all_on = False
