def is_divisible_by_60(y):
    """Check if y can be rearranged to form a number divisible by 60"""
    # Count frequency of each digit
    from collections import Counter
    digit_counts = Counter(y)

    # Total sum of digits
    total_sum = sum(int(digit) * digit_counts[digit] for digit in '0123456789')

    # We need at least one of {0, 2, 4, 6, 8} for divisibility by 20
    # And we need at least one 0 for the last digit
    # Actually, for divisibility by 20, we need:
    # - The last digit to be 0
    # - The second-to-last digit to be 0, 2, 4, 6, or 8
    # So we need at least one 0 and at least one of {0, 2, 4, 6, 8}

    # Check if we have at least one 0
    if digit_counts['0'] < 1:
        return False

    # Check if we have at least one of {0, 2, 4, 6, 8}
    if not any(digit_counts[digit] >= 1 for digit in ['0', '2', '4', '6', '8']):
        return False

    # Check if total sum is divisible by 3
    if total_sum % 3 != 0:
        return False

    return True

def main():
    n = int(input())
    for _ in range(n):
        y = input().strip()
        if is_divisible_by_60(y):
            print("red")
        else:
            print("cyan")

if __name__ == "__main__":
    main()
