import sys
from collections import deque

def solve():
    data = sys.stdin.read().splitlines()
    if not data:
        return
    n = int(data[0].strip())
    names = [line.strip() for line in data[1:n+1]]

    # Build graph for constraints: edge from c to d means c < d
    nodes = 'abcdefghijklmnopqrstuvwxyz'
    adj = {c: set() for c in nodes}
    in_deg = {c: 0 for c in nodes}

    for i in range(n):
        for j in range(i + 1, n):
            s = names[i]
            t = names[j]
            # Check if s > t (standard lexicographical order)
            if s > t:
                k = 0
                while k < len(s) and k < len(t) and s[k] == t[k]:
                    k += 1
                if k < len(s) and k < len(t) and s[k] != t[k]:
                    # First differing position both defined and differ
                    char_s = s[k]
                    char_t = t[k]
                    if char_s != char_t:
                        adj[char_t].add(char_s)
                        in_deg[char_s] += 1

    # Kahn's algorithm for topological sort
    queue = deque()
    for c in nodes:
        if in_deg[c] == 0:
            queue.append(c)

    top_order = []
    while queue:
        u = queue.popleft()
        top_order.append(u)
        for v in adj[u]:
            in_deg[v] -= 1
            if in_deg[v] == 0:
                queue.append(v)

    if len(top_order) == 26:
        print(''.join(top_order))
    else:
        print("Impossible")

if __name__ == '__main__':
    solve()
"}

