import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    t = int(next(it))
    out_lines = []
    for _ in range(t):
        # Skip empty lines
        while True:
            try:
                token = next(it)
                if token.isdigit() or token == '':
                    break
            except StopIteration:
                break

        n = int(next(it))
        m = int(next(it))

        # Read blocked cells
        blocked = set()
        for _ in range(m):
            r = int(next(it))
            c = int(next(it))
            blocked.add((r, c))

        # Count free cells
        free = 0
        for r in range(1, 3):
            for c in range(1, n + 1):
                if (r, c) not in blocked:
                    free += 1

        if free % 2 != 0:
            out_lines.append("NO")
        else:
            out_lines.append("YES")

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
