def can_place_photos(n, m, a):
    """Check if it's possible to place photos without adjacency"""

    # Create a list of available albums with their indices
    available_albums = []
    for i in range(m):
        if a[i] > 0:
            available_albums.append(i)

    # Try to place photos using a more sophisticated greedy strategy
    result = [-1] * n
    for i in range(n):
        # Find an album that has photos and can place in position i
        placed = False

        # Try to place from the album with the most photos
        if available_albums:
            # Check if we can place at position i
            left = (i - 1) % n
            right = (i + 1) % n

            if result[left] != available_albums[0] + 1 and result[right] != available_albums[0] + 1:
                result[i] = available_albums[0] + 1
                a[available_albums[0]] -= 1
                placed = True

        # If not placed, try others
        if not placed:
            for album_idx in available_albums[1:]:
                if a[album_idx] == 0:
                    continue

                left = (i - 1) % n
                right = (i + 1) % n

                if result[left] == album_idx + 1 or result[right] == album_idx + 1:
                    continue

                result[i] = album_idx + 1
                a[album_idx] -= 1
                placed = True
                break

        if not placed:
            return -1

    return result

n, m = map(int, input().split())
a = list(map(int, input().split()))

solution = can_place_photos(n, m, a)

if solution == -1:
    print(-1)
else:
    print(' '.join(map(str, solution)))
