import sys

def find(parent, x):

    if parent[x] != x:
        parent[x] = find(parent, parent[x])
    return parent[x]

def union(parent, rank, x, y):

    px = find(parent, x)
    py = find(parent, y)

    if px == py:
        return False

    if rank[px] < rank[py]:
        parent[px] = py
    else:
        parent[py] = px
        if rank[px] == rank[py]:
            rank[px] += 1
    return True

def rollback(parent, rank, history):

    px, py = history.pop()
    rank[px] -= 1
    if rank[px] < rank[py]:
        parent[px] = py
    else:
        parent[py] = px

    if rank[px] == rank[py]:
        rank[py] -= 1

n, k = map(int, sys.stdin.readline().split())

# DSU arrays
parent = [i for i in range(n)]
rank = [1] * n

# Stack to keep track of union operations (parent, rank changes)
history = []

for _ in range(k):
    parts = sys.stdin.readline().split()
    op = parts[0]
    u = int(parts[1])
    v = int(parts[2])

    if op == '1':
        # Add edge
        if union(parent, rank, u, v):
            # Record the union operation (parent, rank before union)
            # We store (px, py) before the union
            px = find(parent, u)
            py = find(parent, v)
            history.append((px, py))
    elif op == '2':
        # Remove edge
        # We need to undo the union that created this edge
        # Since we only store the union operation, we can just pop
        if history:
            px, py = history.pop()
            # Rollback the union
            rank[px] -= 1
            if rank[px] < rank[py]:
                parent[px] = py
            else:
                parent[py] = px
            if rank[px] == rank[py]:
                rank[py] -= 1
    elif op == '3':
        # Query
        if find(parent, u) == find(parent, v):
            print("YES")
        else:
            print("NO")
