from math import sqrt

def is_winning(x, y):
    """Check if (x, y) is a winning position.
    A position is winning if there exists a move to a losing position.
    A position is losing if all moves lead to winning positions.
    """

    # We want to reach (0, 0)
    if x == 0 and y == 0:
        return False  # This is the target, we've won

    # Check if we can move to a losing position
    for a in range(1, x + 1):
        if is_winning(x - a, y):
            return True

    for b in range(1, y + 1):
        if is_winning(x, y - b):
            return True

    # Check diagonal moves
    max_diag = min(x, y)
    for a in range(1, max_diag + 1):
        if is_winning(x - a, y - a):
            return True

    # If all moves lead to winning positions, this is a losing position
    return False

def solve():
    T = int(input())
    for _ in range(T):
        m, n, p, q = map(int, input().split())
        # Convert to relative coordinates from target
        a = m - p
        b = n - q

        if is_winning(a, b):
            print("Alice")
        else:
            print("Bob")

solve()
