import sys

def compute_score(hand):
    # hand is a list of integers from 1 to 13
    n = len(hand)
    # DP: dp[s] = max score achievable with sum s (0 <= s <= 21)
    dp = [0] * 22  # index 0-21
    # dp[0] = 0 (base case)
    # dp[s] = max score without exceeding 21

    for card in hand:
        new_dp = dp.copy()
        for s in range(22):
            if dp[s] == 0:
                continue
            if card == 1:
                # 1 can be 1 or 11
                # 1 point:
                if s + 1 <= 21:
                    new_dp[s + 1] = max(new_dp[s + 1], dp[s])
                # 11 points:
                if s + 11 <= 21:
                    new_dp[s + 11] = max(new_dp[s + 11], dp[s])
            else:
                # 2-9: score = value; 10-13: score = 10
                score = card if 2 <= card <= 9 else 10
                if s + score <= 21:
                    new_dp[s + score] = max(new_dp[s + score], dp[s])
        dp = new_dp

    # The max score is the maximum in dp[0..21]
    return max(dp)


def solve():
    lines = []
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        lines.append(line)

    i = 0
    while i < len(lines):
        line = lines[i].strip()
        if not line:
            i += 1
            continue
        if line == '0':
            break
        hand = list(map(int, line.split()))
        score = compute_score(hand)
        print(score)
        i += 1

if __name__ == '__main__':
    solve()
