    """Compute the greatest common divisor of two numbers."""
    while b:
        a, b = b, a % b
    return a

def compute_gcd_of_list(nums):
    """Compute the GCD of a list of numbers."""
    if not nums:
        return 0
    result = nums[0]
    for num in nums[1:]:
        result = gcd(result, num)
        if result == 1:
            break  # GCD cannot be smaller than 1
    return result

T = int(input())
for _ in range(T):
    N = int(input())
    strengths = list(map(int, input().split()))
    if 0 in strengths:
        # If there's at least one 0, return the maximum non-zero strength
        non_zero = [num for num in strengths if num != 0]
        if non_zero:
            print(max(non_zero))
        else:
            print(0)
    else:
        print(compute_gcd_of_list(strengths))

