MOD = 10**9 + 7

n, m = map(int, input().split())
p = input().strip()
y_list = list(map(int, input().split()))

# Check if m == 0
if m == 0:
    # All positions are free
    print(pow(26, n, MOD))
else:
    # Check consistency and count free positions
    fixed = {}
    consistent = True

    for y in y_list:
        # y is 1-indexed, convert to 0-indexed
        start = y - 1

        # Check if this match is consistent with previous matches
        for j in range(len(p)):
            pos = start + j
            expected_char = p[j]

            # Check if this position is already fixed
            if pos in fixed:
                if fixed[pos] != expected_char:
                    consistent = False
                    break
            else:
                fixed[pos] = expected_char

        if not consistent:
            break

    if not consistent:
        print(0)
    else:
        # Count free positions
        free_positions = n - len(fixed)
        print(pow(26, free_positions, MOD))
