import sys
from collections import Counter

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    t = int(data[0])
    a = list(map(int, data[1:1+t]))

    freq = Counter(a)

    # Try all possible n and m such that n * m = t
    for n in range(1, int(t**0.5) + 1):
        if t % n == 0:
            m = t // n

            # Try all possible positions of 0
            for x in range(1, n + 1):
                for y in range(1, m + 1):
                    # Count how many cells have each Manhattan distance from (x, y)
                    distance_counts = Counter()
                    for i in range(1, n + 1):
                        for j in range(1, m + 1):
                            dist = abs(i - x) + abs(j - y)
                            distance_counts[dist] += 1

                    # Check if the distances match the input
                    match = True
                    for d in distance_counts:
                        if freq.get(d, 0) != distance_counts[d]:
                            match = False
                            break
                    if match:
                        print(n, m)
                        print(x, y)
                        return

    print(-1)

if __name__ == "__main__":
    solve()
