import math

def is_losing_position(x, y):
    """Check if (x, y) is a losing position in Wythoff's game"""
    if x > y:
        x, y = y, x

    k = y - x

    # Golden ratio
    phi = (1 + math.sqrt(5)) / 2
    a = int(k * phi)

    # Check if (a, a + k) == (x, y) or (a + k, a)
    if (a, a + k) == (x, y) or (a, a + k) == (y, x):
        return True

    return False

def solve():
    T = int(input())

    for _ in range(T):
        m, n, p, q = map(int, input().split())
        x = m - p
        y = n - q

        if is_losing_position(x, y):
            print("Bob")
        else:
            print("Alice")

solve()
